"""Safe, deterministic generated-file management."""

from __future__ import annotations

import os
from collections import OrderedDict
from collections.abc import Iterable, Mapping
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from tempfile import NamedTemporaryFile

from .exceptions import CodegenError

GENERATED_HEADER = (
    "# Code generated by smithy-python. DO NOT EDIT.\n"
    "# SPDX-License-Identifier: Apache-2.0\n"
)


@dataclass(frozen=True, slots=True)
class GeneratedFile:
    path: PurePosixPath
    contents: str


class FileManifest:
    """Collects generated files and writes them atomically under a base directory."""

    def __init__(self, base_dir: Path) -> None:
        self.base_dir = base_dir.resolve()
        self._files: OrderedDict[PurePosixPath, str] = OrderedDict()

    @property
    def files(self) -> Mapping[PurePosixPath, str]:
        return self._files.copy()

    def write(self, path: str | PurePosixPath, contents: str) -> None:
        path = _safe_path(path)
        self._files[path] = contents

    def append(self, path: str | PurePosixPath, contents: str) -> None:
        path = _safe_path(path)
        self._files[path] = self._files.get(path, "") + contents

    def flush(self) -> tuple[Path, ...]:
        written: list[Path] = []
        self.base_dir.mkdir(parents=True, exist_ok=True)
        for relative, contents in self._files.items():
            destination = (self.base_dir / relative).resolve()
            if not destination.is_relative_to(self.base_dir):
                raise CodegenError(
                    f"Generated path escapes output directory: {relative}"
                )
            destination.parent.mkdir(parents=True, exist_ok=True)
            with NamedTemporaryFile(
                mode="w",
                encoding="utf-8",
                dir=destination.parent,
                prefix=f".{destination.name}.",
                delete=False,
            ) as temporary:
                temporary.write(contents)
                temporary_path = Path(temporary.name)
            os.replace(temporary_path, destination)
            written.append(destination)
        return tuple(written)


class PythonWriter:
    """Small import-aware writer for complete Python modules."""

    def __init__(self) -> None:
        self._stdlib: set[tuple[str, str | None]] = set()
        self._third_party: set[tuple[str, str | None]] = set()
        self._local: set[tuple[str, str | None]] = set()
        self._body: list[str] = []

    def import_(
        self,
        module: str,
        name: str | None = None,
        *,
        category: str = "third_party",
    ) -> None:
        target = {
            "stdlib": self._stdlib,
            "third_party": self._third_party,
            "local": self._local,
        }[category]
        target.add((module, name))

    def write(self, value: str = "") -> None:
        self._body.append(value.rstrip())

    def render(self, *, future_annotations: bool = True) -> str:
        chunks = [GENERATED_HEADER.rstrip(), ""]
        if future_annotations:
            chunks.extend(("from __future__ import annotations", ""))
        for imports in (self._stdlib, self._third_party, self._local):
            if imports:
                chunks.extend(_render_imports(imports))
                chunks.append("")
        chunks.extend(self._body)
        return "\n".join(chunks).rstrip() + "\n"


def _render_imports(imports: Iterable[tuple[str, str | None]]) -> list[str]:
    plain = sorted(module for module, name in imports if name is None)
    named: dict[str, list[str]] = {}
    for module, name in imports:
        if name is not None:
            named.setdefault(module, []).append(name)
    result = [f"import {module}" for module in plain]
    for module in sorted(named):
        names = sorted(set(named[module]))
        result.append(f"from {module} import {', '.join(names)}")
    return result


def _safe_path(value: str | PurePosixPath) -> PurePosixPath:
    path = PurePosixPath(value)
    if path.is_absolute() or ".." in path.parts or not path.parts:
        raise CodegenError(f"Generated paths must be relative and contained: {value}")
    return path
